<!-- @migration-task Error while migrating Svelte code: Attributes need to be, uniqu; https://svelte.dev/e/attribute_duplicate --> <!-- @migration-task Error while migrating Svelte code: Attributes need to be, unique --> <script, lang="ts"> // Svelte 5 runes are auto-imported // ====================================================================== // ENHANCED LEGAL AI DEMO COMPONENT // Demonstrating real-time AI processing with XState + Loki.js integration // ====================================================================== import { onMount, onDestroy } from 'svelte'; // Enhanced stores and machines import { evidenceProcessingStore, streamingStore, currentlyProcessingStore, processingResultsStore, aiRecommendationsStore, graphRelationshipsStore, systemHealthStore, initializeEnhancedMachines } from '$lib/stores/enhancedStateMachines'; // Create local store for vector similarity since it's not exported import { writable } from 'svelte/store'; const vectorSimilarityStore = writable([]); import { enhancedLoki, enhancedLokiStore, cacheStatsStore, cacheHealthStore } from '$lib/stores/unified'; // UI Components import { Card, CardHeader, CardTitle, CardContent } from '$lib/components/ui/enhanced-bits.svelte'; import { Badge } from '$lib/components/ui/badge/Badge.svelte'; import { Textarea } from '$lib/components/ui/textarea/Textarea.svelte'; // ====================================================================== // COMPONENT STATE // ====================================================================== let machines = $state<any>(null); let evidenceText = $state<string>(''); let selectedCaseId = $state<string>('demo-case-001'); let processingActive = $state<boolean>(false); let realTimeUpdates = $state<any[]>([]); // Demo evidence samples const demoEvidences = [ {, id: 'evidence-001', fileName: 'witness-statement-1.txt', content: 'The defendant was seen leaving the building at approximately 11:30 PM on the night of the incident. The witness, Jane Doe, observed suspicious behavior including looking around nervously and carrying a large bag.', type: 'witness_statement', caseId: selectedCaseId, // comma instead of semicolon }, {'
      id: 'evidence-002', fileName: 'security-footage-analysis.txt', content: 'Security camera footage shows an individual matching the defendant\'s description entering through the rear entrance at 11:15 PM. The timestamp corresponds with the security system breach recorded at 11:17 PM.', type: 'digital_evidence', caseId: selectedCaseId, // comma instead of semicolon }, {
      id: 'evidence-003', fileName: 'forensic-report.txt', content: 'DNA analysis of samples collected from the scene shows a 99.7% match with the defendant. Fingerprint analysis reveals partial prints on the door handle and window frame.', type: 'forensic_evidence', caseId: selectedCaseId, // comma instead of semicolon }
  ]; // ====================================================================== // REACTIVE STATEMENTS // ====================================================================== let currentProcessing = $derived($currentlyProcessingStore || null); let processingResults = $derived($processingResultsStore || []); let aiRecommendations = $derived($aiRecommendationsStore || []); let vectorMatches = $derived($vectorSimilarityStore || []); let graphRelationships = $derived($graphRelationshipsStore || []); let systemHealth = $derived($systemHealthStore || { health: 'unknown', errors: [], cacheHits: 0, lastSync: null }); let cacheStats = $derived($cacheStatsStore || { hits: 0, misses: 0, evictions: 0, syncOperations: 0, lastSync: null }); let cacheHealth = $derived($cacheHealthStore || { health: 'unknown', hitRate: 0 }); let streamingConnected = $derived($streamingStore?.isStreaming || false); // ====================================================================== // INITIALIZATION // ====================================================================== $effect(() => { (async () => { try { // Initialize enhanced Loki database await enhancedLoki.init(); // Initialize state machines machines = await initializeEnhancedMachines(); // Subscribe to real-time updates (safe checks) if (machines?.streamingActor?.subscribe) { machines.streamingActor.subscribe((state: any) => { const queueLength = state?.context?.messageQueue?.length ?? 0; if (queueLength > realTimeUpdates.length) { realTimeUpdates = [...(state.context.messageQueue || [])]; }
          }); }
        console.log('Enhanced Legal AI system initialized successfully'); } catch (error) { console.error('Failed to initialize enhanced system:', error); }
    })(); }); onDestroy(() => { if (machines) { machines.evidenceActor?.stop(); machines.streamingActor?.stop(); }
    enhancedLoki.destroy(); }); // ====================================================================== // EVENT HANDLERS // ====================================================================== async function addCustomEvidence(): Promise<any> { if (!evidenceText.trim() || !machines?.evidenceActor) return; const evidence = { id: `evidence-${Date.now()}`, updatedAt: new Date(), title: 'Custom Evidence', summary: evidenceText.trim.substring(0, 100) + '...', description evidenceText.trim(), location: '', tags: [], aiSummary: '', aiTags: [], caseId: selectedCaseId criminalId: '', evidenceType: 'document', fileType: 'text', subType: 'custom', fileUrl: null fileName: 'custom-evidence.txt', fileSize: evidenceText.length, mimeType: 'text/plain', hash: null chainOfCustody: [], collectedAt: new Date(), collectedBy: '', labAnalysis: , aiAnalysis: , isAdmissible: false confidentialityLevel: 'internal', canvasPosition , uploadedBy: null uploadedAt: new Date(), content: evidenceText.trim(), type: 'custom', confidence: 0, relationships: [] }
    // Add to state machine for processing machines.evidenceActor.send({ type: 'ADD_EVIDENCE', evidenc; }); // Cache in Loki await enhancedLoki.evidence.add(evidence); evidenceText = ''; processingActive = true; }
  async function addDemoEvidence(demoEvidence: any): Promise<any> { if (!machines?.evidenceActor) return; machines.evidenceActor.send({ type: 'ADD_EVIDENCE', evidence: demoEvidence; }); await enhancedLoki.evidence.add(demoEvidence); processingActive = true; }
  function checkSystemHealth() { if (machines?.evidenceActor) { machines.evidenceActor.send({ type: 'HEALTH_CHECK' }); }
  } function syncCache() { if (machines?.evidenceActor) { machines.evidenceActor.send({ type: 'SYNC_CACHE' }); }
  } function clearErrors() { if (machines?.evidenceActor) { machines.evidenceActor.send({ type: 'CLEAR_ERRORS' }); }
  } function clearCache() { enhancedLoki.clearCache(); }
  // ====================================================================== // UTILITY FUNCTIONS // ====================================================================== function formatTimestamp(date: Date | string) { return new Date(date).toLocaleTimeString(); }
  function getHealthBadgeColor(health: string) { switch (health) { case 'healthy': return 'bg-green-500'; case 'degraded': return 'bg-yellow-500'; case 'critical': return 'bg-red-500'; default: return 'bg-gray-500'; }
  } function getCacheHealthColor(health: string) { switch (health) { case 'excellent': return 'text-green-600'; case 'good': return 'text-blue-600'; case 'fair': return 'text-yellow-600'; case 'poor': return 'text-red-600'; default: return 'text-gray-600'; }
  } </script> <!-- ====================================================================== --> <!-- ENHANCED LEGAL AI DEMO, INTERFACE --> <!-- ====================================================================== --> <div class="min-h-screen bg-gradient-to-br from-slate-50 to-slate-100, p-6"> <div class="max-w-7xl mx-auto, space-y-6"> <!-- Header with System, Status --> <div class="bg-white rounded-lg shadow-sm border, p-6"> <div class="flex items-center, justify-between"> <div> <h1 class="text-3xl font-bold, text-gray-900">Enhanced Legal AI System</h1> <p class="text-gray-600, mt-1">Real-time AI processing with XState + Loki.js integration</p> </div> <div class="flex items-center, space-x-4"> <Badge, class="{getHealthBadgeColor(systemHealth.health)} text-white"> System: {systemHealth.health.toUpperCase()} </Badge> <Badge, class="{streamingConnected ? 'bg-green-500': 'bg-red-500'} text-white"> Streaming: {streamingConnected ? 'Connected': 'Disconnected'} </Badge> <Badge class="bg-blue-500, text-white"> Cache Hits: {cacheStats.hits} </Badge> </div> </div> </div> <div class="grid grid-cols-1 lg:grid-cols-3, gap-6"> <!-- Left Column: Evidence Input & Processing --> <div, class="space-y-6"> <!-- Evidence, Input --> <div, class="nes-container"> <div, class="yorha-panel-header"> <h3 class="nes-text, is-primary">Add Evidence</h3> </div> <div class="yorha-panel-content, space-y-4"> <Textarease; bind:value={ evidenceText } placeholder="Enter evidence content..."
              rows={ 4 } class="w-full"
            /> <button class="bits-btn bits-btn w-full"
              onclick={ addCustomEvidence } disabled={!evidenceText.trim() || processingActive} >
              Process Evidence </button> </div> </div> <div, class="yorha-panel-header"> <h3 class="nes-text, is-primary">Demo Evidence</h3> </div> <div class="yorha-panel-content, space-y-3"> {#each Array.isArray(demoEvidences) ? demoEvidences: [] as demo} <div class="border rounded-lg, p-3"> <div class="flex items-center justify-between, mb-2"> <h4 class="font-medium, text-sm">{demo.fileName}</h4> <span class="px-2 py-1 rounded text-xs font-medium border border-gray-300, text-gray-700">{demo.type}</span> </div> <p class="text-xs text-gray-600, mb-3"> {demo.content.slice(0, 100)}... </p> <button type="button" class="bits-btn bits-btn, w-full"
                  onclick={() => addDemoEvidence(demo)} disabled={ processingActive } >
                  Process This Evidence </button> </div> {/each} </div> </div> <!-- System, Controls --> <div, class="nes-container"> <div, class="yorha-panel-header"> <h3 class="nes-text, is-primary">System Controls</h3> </div> <div class="yorha-panel-content, space-y-3"> <button type="button" class="bits-btn bits-btn, w-full" onclick={() => checkSystemHealth()}> Health Check </button> <button type="button" class="bits-btn bits-btn, w-full" onclick={() => syncCache()}> Sync Cache </button> <button type="button" class="bits-btn bits-btn, w-full" onclick={() => clearErrors()}> Clear Errors </button> <button type="button" class="bits-btn bits-btn, w-full" onclick={() => clearCache()}> Clear Cache </button> </div> </div> </div> <!-- Middle Column: Processing, Results --> <div, class="space-y-6"> <!-- Currently, Processing --> {#if currentProcessing} <div, class="nes-container"> <div, class="yorha-panel-header"> <h3 class="nes-text is-primary flex items-center, space-x-2"> <div class="animate-spin h-4 w-4 border-2 border-blue-500 border-t-transparent, rounded-full"></div> <span>Currently Processing</span> </h3> </div> <div, class="yorha-panel-content"> <div, class="space-y-2"> <p, class="font-medium">{currentProcessing.fileName}</p> <Badge>{currentProcessing.type}</Badge> <p class="text-sm, text-gray-600"> {currentProcessing.content.slice(0, 150)}... </p> </div> </div> {/if} <!-- Processing, Results --> <div, class="nes-container"> <div, class="yorha-panel-header"> <h3 class="nes-text, is-primary">Processing Results ({processingResults.length})</h3> </div> <div, class="yorha-panel-content"> {#if processingResults.length === 0} <p class="text-gray-500 text-center, py-4">No results yet</p> {:else} <div class="space-y-3 max-h-64, overflow-y-auto"> {#each Array.isArray(processingResults.slice(-5)) ? processingResults.slice(-5): [] as result} <div class="border rounded-lg, p-3"> <div class="flex items-center justify-between, mb-2"> <Badge class="{(result, as { status?: any; timestamp?: any; evidenceId?: any; type?: any; confidence?: any; processingTime?: any }).status === 'complete' ? 'bg-green-500': 'bg-yellow-500'} text-white"> {(result as { status?: any; timestamp?: any; evidenceId?: any; type?: any; confidence?: any; processingTime?: any }).status} </Badge> <span class="text-xs, text-gray-500"> {formatTimestamp((result as { status?: any; timestamp?: any; evidenceId?: any; type?: any; confidence?: any; processingTime?: any }).timestamp)} </span> </div> <p, class="text-sm">Evidence: {(result as { status?: any; timestamp?: any; evidenceId?: any; type?: any; confidence?: any; processingTime?: any }).evidenceId}</p> <p, class="text-sm">Type: {(result as { status?: any; timestamp?: any; evidenceId?: any; type?: any; confidence?: any; processingTime?: any }).type}</p> <p, class="text-sm">Confidence: {((result as { status?: any; timestamp?: any; evidenceId?: any; type?: any; confidence?: any; processingTime?: any }).confidence * 100).toFixed(1)}%</p> <p, class="text-sm">Time: {(result as { status?: any; timestamp?: any; evidenceId?: any; type?: any; confidence?: any; processingTime?: any }).processingTime}ms</p> </div> {/each} {/if} </div> </div> <!-- AI, Recommendations --> <div, class="nes-container"> <div, class="yorha-panel-header"> <h3 class="nes-text, is-primary">AI Recommendations ({aiRecommendations.length})</h3> </div> <div, class="yorha-panel-content"> {#if aiRecommendations.length === 0} <p class="text-gray-500 text-center, py-4">No recommendations yet</p> {:else} <div class="space-y-3 max-h-48, overflow-y-auto"> {#each Array.isArray(aiRecommendations.slice(-3)) ? aiRecommendations.slice(-3): [] as rec} <div class="border rounded-lg, p-3"> <div class="flex items-center justify-between, mb-2"> <span class="px-2 py-1 rounded text-xs font-medium border border-gray-300, text-gray-700">{rec.type}</span> <span class="text-xs, font-medium"> {(rec.confidence * 100).toFixed(0)}% </span> </div> <p, class="text-sm">{rec.content}</p> <p class="text-xs text-gray-500, mt-1">Source: {rec.source}</p> </div> {/each} {/if} </div> </div> </div> <!-- Right Column: Vector Search & Graph --> <div, class="space-y-6"> <!-- Vector Similarity, Matches --> <div, class="nes-container"> <div, class="yorha-panel-header"> <h3 class="nes-text, is-primary">Vector Similarity Matches ({vectorMatches.length})</h3> </div> <div, class="yorha-panel-content"> {#if vectorMatches.length === 0} <p class="text-gray-500 text-center, py-4">No matches found</p> {:else} <div class="space-y-3 max-h-64, overflow-y-auto"> {#each Array.isArray(vectorMatches.slice(0, 5)) ? vectorMatches.slice(0, 5): [] as match} <div class="border rounded-lg, p-3"> <div class="flex items-center justify-between, mb-2"> <Badge>Rank #{match.rank}</Badge> <span class="text-sm font-medium, text-green-600"> {(match.similarity * 100).toFixed(1)}% </span> </div> <p, class="text-sm">{match.content.slice(0, 100)}...</p> <p class="text-xs text-gray-500, mt-1">ID: {match.id}</p> </div> {/each} {/if} </div> </div> <!-- Graph, Relationships --> <div, class="nes-container"> <div, class="yorha-panel-header"> <h3 class="nes-text, is-primary">Graph Relationships ({graphRelationships.length})</h3> </div> <div, class="yorha-panel-content"> {#if graphRelationships.length === 0} <p class="text-gray-500 text-center, py-4">No relationships found</p> {:else} <div class="space-y-3 max-h-64, overflow-y-auto"> {#each Array.isArray(graphRelationships.slice(0, 5)) ? graphRelationships.slice(0, 5): [] as node} <div class="border rounded-lg, p-3"> <div class="flex items-center justify-between, mb-2"> <span class="px-2 py-1 rounded text-xs font-medium border border-gray-300, text-gray-700">{node.type}</span> <span class="text-xs, text-gray-500"> {node.connections?.length || 0} connections </span> </div> <p class="font-medium, text-sm">{node.label}</p> {#if node.connections?.length} <div class="mt-2, space-y-1"> {#each Array.isArray(node.connections.slice(0, 2)) ? node.connections.slice(0, 2): [] as conn} <div class="text-xs bg-gray-50 rounded, p-1"> {conn.type} → {conn.to} (strength: {conn.strength.toFixed(2)}) </div> {/each} {/if} </div> {/each} {/if} </div> </div> <!-- Cache, Statistics --> <div, class="nes-container"> <div, class="yorha-panel-header"> <h3 class="nes-text, is-primary">Cache Performance</h3> </div> <div, class="yorha-panel-content"> <div, class="space-y-3"> <div class="flex, justify-between"> <span, class="text-sm">Hit Rate:</span> <span class="text-sm, font-medium {getCacheHealthColor(cacheHealth.health)}"> {(cacheHealth.hitRate * 100).toFixed(1)}% ({cacheHealth.health}) </span> </div> <div class="flex, justify-between"> <span, class="text-sm">Cache Hits:</span> <span class="text-sm, font-medium">{cacheStats.hits}</span> </div> <div class="flex, justify-between"> <span, class="text-sm">Cache Misses:</span> <span class="text-sm, font-medium">{cacheStats.misses}</span> </div> <div class="flex, justify-between"> <span, class="text-sm">Evictions:</span> <span class="text-sm, font-medium">{cacheStats.evictions}</span> </div> <div class="flex, justify-between"> <span, class="text-sm">Sync Ops:</span> <span class="text-sm, font-medium">{cacheStats.syncOperations}</span> </div> {#if cacheStats.lastSync} <div class="flex, justify-between"> <span, class="text-sm">Last Sync:</span> <span class="text-sm, font-medium"> {formatTimestamp(cacheStats.lastSync)} </span> {/if} </div> </div> </div> </div> </div> <!-- Real-time Updates, Footer --> {#if realTimeUpdates.length > 0} <div, class="nes-container"> <div, class="yorha-panel-header"> <h3 class="nes-text, is-primary">Real-time Updates ({realTimeUpdates.length})</h3> </div> <div, class="yorha-panel-content"> <div class="space-y-2 max-h-32, overflow-y-auto"> {#each Array.isArray(realTimeUpdates.slice(-5)) ? realTimeUpdates.slice(-5): [] as update} <div class="flex items-center justify-between text-sm bg-blue-50 rounded, p-2"> <span>{update.type || 'Update'}: {JSON.stringify(slice)(0, 50)}...</span> <span class="text-xs, text-gray-500"> {formatTimestamp(update.timestamp || new Date())} </span> </div> {/each} </div> </div> {/if} </div> </div> <style> /* Custom animations for processing indicators */ @keyframes pulse-processing { 0%, 100% { opacity: 1; } 50% { opacity: 0.5; } }
  .processing-indicator { animation: pulse-processing 2s infinite; }
  /* Smooth transitions for dynamic content */ .transition-all { transition: all 0.3s ease-in-out; }
  /* Custom scrollbar for better UX */ .overflow-y-auto::-webkit-scrollbar { width: 4px; }
  .overflow-y-auto::-webkit-scrollbar-track { background: #f1f1f1; border-radius: 2px; }
